/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
 * };
 */
class Solution {
public:
    TreeNode* deleteNode(TreeNode* root, int key) {
        TreeNode* parent = nullptr;
        TreeNode* cur = root;
        while (cur && cur->val != key) {
            parent = cur;
            if (key < cur->val) cur = cur->left;
            else cur = cur->right;
        }
        if (!cur) return root; // key not found

        // Node has two children: replace with inorder successor.
        if (cur->left && cur->right) {
            TreeNode* succParent = cur;
            TreeNode* succ = cur->right;
            while (succ->left) {
                succParent = succ;
                succ = succ->left;
            }
            cur->val = succ->val;
            // Unlink succ (it has at most a right child).
            TreeNode* succChild = succ->right;
            if (succParent->left == succ) succParent->left = succChild;
            else succParent->right = succChild;
            delete succ;
            return root;
        }

        // Node has at most one child: splice it out.
        TreeNode* child = cur->left ? cur->left : cur->right;
        if (!parent) {
            delete cur;
            return child; // deleted the root
        }
        if (parent->left == cur) parent->left = child;
        else parent->right = child;
        delete cur;
        return root;
    }
};
